(4568455, 657213, 15711, '<td valign="top">What a stand out - even from the thumbs.  Good luck.</td>', 'What a stand out - even from the thumbs.  Good luck.', '2008-03-17 00:24:30.000000', NULL, 1),
(4568463, 658315, 15711, '<td valign="top">Love the softness.  I would definitely remove the harsh orange border. ;~)</td>', 'Love the softness.  I would definitely remove the harsh orange border. ;~)', '2008-03-17 00:27:09.000000', NULL, 1),
(4568466, 658307, 42013, '<td valign="top">Delightful. Love the balance.</td>', 'Delightful. Love the balance.', '2008-03-17 00:27:54.000000', NULL, 1),
(4568470, 657714, 86359, '<td valign="top">Take off your lens cap before trying to take a picture</td>', 'Take off your lens cap before trying to take a picture', '2008-03-17 00:29:17.000000', NULL, 1),
(4568587, 658521, 82985, '<td valign="top">while this doesn''t seem "harsh" to me, the image is simply superb. Wonderful forms, flow, feel, and tonality.  10</td>', 'while this doesn''t seem "harsh" to me, the image is simply superb. Wonderful forms, flow, feel, and tonality.  10', '2008-03-17 01:16:37.000000', NULL, 1),
(4568588, 658688, 82985, '<td valign="top">I really like this image, nicely composed chaotic setting.  I find the title of the image sort of irrelevant at best, and distracting for certain.  I think this image speaks to harshness and aridity very well on its own.  9</td>', 'I really like this image, nicely composed chaotic setting.  I find the title of the image sort of irrelevant at best, and distracting for certain.  I think this image speaks to harshness and aridity very well on its own.  9', '2008-03-17 01:16:40.000000', NULL, 1),
(4568591, 658802, 9763, '<td valign="top">I wish I could get out there, but I don''t have 4wd.  Great shot!  Excellent focus!  The sky is a bit magenta and cyan, but it''s really pretty!</td>', 'I wish I could get out there, but I don''t have 4wd.  Great shot!  Excellent focus!  The sky is a bit magenta and cyan, but it''s really pretty!', '2008-03-17 01:18:56.000000', NULL, 1),
(4568593, 658631, 82985, '<td valign="top">very well done.  I like the off-center composition and the sense of place, the dominance of the red element.  I think it might look better with a crop off the bottom (say 15% or so), but that is a nitpick even if true....  9</td>', 'very well done.  I like the off-center composition and the sense of place, the dominance of the red element.  I think it might look better with a crop off the bottom (say 15% or so), but that is a nitpick even if true....  9', '2008-03-17 01:19:30.000000', NULL, 1),
(4568597, 657343, 82985, '<td valign="top">Just wonderful.  If there is texture available in the snowy foreground (just a taste is all) it might be worth  some work to bring it out  9</td>', 'Just wonderful.  If there is texture available in the snowy foreground (just a taste is all) it might be worth  some work to bring it out  9', '2008-03-17 01:21:09.000000', NULL, 1),
(4568599, 658792, 9763, '<td valign="top">I was there this weekend too!  Nice composition.  A bit lacking in constrast, but it''s a really classic photo!</td>', 'I was there this weekend too!  Nice composition.  A bit lacking in constrast, but it''s a really classic photo!', '2008-03-17 01:22:21.000000', NULL, 1),
(4568601, 657213, 82985, '<td valign="top">Okay--full disclosure: I am a sucker for images with this kind of texture.  I would like this with or without the model, and the colors, tones, textures are great.  I might even like it better without the model..  8</td>', 'Okay--full disclosure: I am a sucker for images with this kind of texture.  I would like this with or without the model, and the colors, tones, textures are great.  I might even like it better without the model..  8', '2008-03-17 01:23:09.000000', NULL, 1),
