(4570519, 656768, 22459, '<td valign="top">Very nice macro, fits the challenge well but on the downside I will subtract 1 for not having the eye of the dragonfly as sharp as possible. Golden rule of macro''s concentrate on the eye.8</td>', 'Very nice macro, fits the challenge well but on the downside I will subtract 1 for not having the eye of the dragonfly as sharp as possible. Golden rule of macro''s concentrate on the eye.8', '2008-03-17 23:42:52.000000', NULL, 1),
(4570525, 658803, 22459, '<td valign="top">Very harsh indeed. I would have prefered to seen more B/W contrast looks a bit flat to me.</td>', 'Very harsh indeed. I would have prefered to seen more B/W contrast looks a bit flat to me.', '2008-03-17 23:44:56.000000', NULL, 1),
