(4570539, 658031, 22459, '<td valign="top">Very harsh for all concerned. I''m not real keen on the bottom right of the picture, perhaps a different angle would have suited.</td>', 'Very harsh for all concerned. I''m not real keen on the bottom right of the picture, perhaps a different angle would have suited.', '2008-03-18 00:04:11.000000', NULL, 1),
(4570542, 658750, 22459, '<td valign="top">There is so much to like about this image, colors, subject,subject matter, the intrigue and the list goes on. Great work.</td>', 'There is so much to like about this image, colors, subject,subject matter, the intrigue and the list goes on. Great work.', '2008-03-18 00:05:43.000000', NULL, 1),
(4570544, 657029, 22459, '<td valign="top">great prespective and those eyes really sell the story, well done.</td>', 'great prespective and those eyes really sell the story, well done.', '2008-03-18 00:06:26.000000', NULL, 1),
(4570546, 658337, 22459, '<td valign="top">It is harsh but it looks like fun,good action shot.</td>', 'It is harsh but it looks like fun,good action shot.', '2008-03-18 00:07:21.000000', NULL, 1),
