(4573151, 658514, 89230, '<td valign="top">I like the field of flowers and the idea of the shot. The sky is way overexposed though.</td>', 'I like the field of flowers and the idea of the shot. The sky is way overexposed though.', '2008-03-19 06:26:43.000000', NULL, 1),
(4573154, 658702, 40853, '<td valign="top">Amen!</td>', 'Amen!', '2008-03-19 06:27:41.000000', NULL, 1),
