(4576449, 658212, 68514, '<td valign="top">A strange beach and a nice shot but it lacks of human presence. 7</td>', 'A strange beach and a nice shot but it lacks of human presence. 7', '2008-03-20 10:27:18.000000', NULL, 1),
(4576467, 657697, 70875, '<td valign="top">Great contrast and antithesis. The background looks very intimidating for walking in to it.</td>', 'Great contrast and antithesis. The background looks very intimidating for walking in to it.', '2008-03-20 10:34:51.000000', NULL, 1),
(4576468, 658084, 70875, '<td valign="top">Great perspective.</td>', 'Great perspective.', '2008-03-20 10:35:11.000000', NULL, 1),
