INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4576740, 657728, 58457, '<td valign="top">with as much symmetry as there is in this photo, I think I''d like to see it completely centered....  but otherwise good job on what was probably a tough exposure.</td>', 'with as much symmetry as there is in this photo, I think I''d like to see it completely centered....  but otherwise good job on what was probably a tough exposure.', '2008-03-20 12:36:44.000000', NULL, 1),
(4576741, 658548, 58457, '<td valign="top">brutal!  good capture!</td>', 'brutal!  good capture!', '2008-03-20 12:36:57.000000', NULL, 1),
(4576743, 658212, 58457, '<td valign="top">ha!  thats pretty funny with the umbrella and snowshoes.  good funny take on what most people interpreted more seriously.</td>', 'ha!  thats pretty funny with the umbrella and snowshoes.  good funny take on what most people interpreted more seriously.', '2008-03-20 12:38:50.000000', NULL, 1),
(4576759, 658521, 22840, '<td valign="top">Beautiful shot!</td>', 'Beautiful shot!', '2008-03-20 12:46:28.000000', NULL, 1),
(4576793, 658049, 58457, '<td valign="top">interesting choice on the rotation.  I wonder if the blown out sky were cropped if it would help the overall composition...</td>', 'interesting choice on the rotation.  I wonder if the blown out sky were cropped if it would help the overall composition...', '2008-03-20 12:58:55.000000', NULL, 1),
(4576802, 658243, 58457, '<td valign="top">I like the texture of the rocks in the foreground vs. the mist/fog in the distance.</td>', 'I like the texture of the rocks in the foreground vs. the mist/fog in the distance.', '2008-03-20 13:01:45.000000', NULL, 1),
(4576815, 658730, 58457, '<td valign="top">I like the geometric architecture and the wide angle composition as well as the greenish tone to it, but it just isn''t so harsh as some others in the challenge.</td>', 'I like the geometric architecture and the wide angle composition as well as the greenish tone to it, but it just isn''t so harsh as some others in the challenge.', '2008-03-20 13:04:29.000000', NULL, 1),
(4576820, 658074, 36606, '<td valign="top">looks crazy. Great photo. Although I would hate to have hadsuch a wedding.9</td>', 'looks crazy. Great photo. Although I would hate to have hadsuch a wedding.9', '2008-03-20 13:05:05.000000', NULL, 1),
(4576838, 657697, 58457, '<td valign="top">definitely a spookier feel with the vignetting... did you add it in post processing?</td>', 'definitely a spookier feel with the vignetting... did you add it in post processing?', '2008-03-20 13:07:38.000000', NULL, 1),
(4576844, 657235, 58457, '<td valign="top">this is like a scene out of lord of the gings or something... very fantasyish...</td>', 'this is like a scene out of lord of the gings or something... very fantasyish...', '2008-03-20 13:09:20.000000', NULL, 1),
(4576955, 658198, 83313, '<td valign="top">I like this. The partial desaturation gives it some eye-leading impact that I like.</td>', 'I like this. The partial desaturation gives it some eye-leading impact that I like.', '2008-03-20 13:36:36.000000', NULL, 1),
(4576957, 658548, 83313, '<td valign="top">Glad I''m not a frog! Nice and eye-pleasing.</td>', 'Glad I''m not a frog! Nice and eye-pleasing.', '2008-03-20 13:37:33.000000', NULL, 1),
(4576961, 658683, 83313, '<td valign="top">Comp seems kind of plain. Perhaps a closer view of the rubble, with the stacks peeping over them might have worked better for impact. I also see a fair amount of noise or compression artifacts in the sky.</td>', 'Comp seems kind of plain. Perhaps a closer view of the rubble, with the stacks peeping over them might have worked better for impact. I also see a fair amount of noise or compression artifacts in the sky.', '2008-03-20 13:40:28.000000', NULL, 1),
(4576966, 658716, 83313, '<td valign="top">Nice idea. Not wowing me though. Not sure quite why.</td>', 'Nice idea. Not wowing me though. Not sure quite why.', '2008-03-20 13:42:23.000000', NULL, 1),
(4576968, 658803, 83313, '<td valign="top">Is this the "cathedral of junk" that I have heard about?</td>', 'Is this the "cathedral of junk" that I have heard about?', '2008-03-20 13:43:07.000000', NULL, 1),
(4576974, 658763, 83313, '<td valign="top">Harsh, but lovley. Had your parka on though, right?</td>', 'Harsh, but lovley. Had your parka on though, right?', '2008-03-20 13:43:47.000000', NULL, 1),
(4576978, 658712, 83313, '<td valign="top">I wanted to say it was "cool looking", but that did not fit. S''nice.</td>', 'I wanted to say it was "cool looking", but that did not fit. S''nice.', '2008-03-20 13:45:15.000000', NULL, 1),
(4576982, 658199, 83313, '<td valign="top">Looks grim and foreboding.</td>', 'Looks grim and foreboding.', '2008-03-20 13:46:03.000000', NULL, 1),
(4576986, 658485, 83313, '<td valign="top">Good comp and I like the treatment. Seems like an illustration form an old book.</td>', 'Good comp and I like the treatment. Seems like an illustration form an old book.', '2008-03-20 13:47:18.000000', NULL, 1),
(4576988, 658736, 83313, '<td valign="top">Nice, though Big Ben seems a bit oversaturated and oversharpened.</td>', 'Nice, though Big Ben seems a bit oversaturated and oversharpened.', '2008-03-20 13:49:00.000000', NULL, 1),
(4576993, 657790, 83313, '<td valign="top">It''s a nice enough sunset, but it does not stand out from a lot of other sunset shots I''ve seen. Maybe too much of the water in the frame. Not sure what to suggest.</td>', 'It''s a nice enough sunset, but it does not stand out from a lot of other sunset shots I''ve seen. Maybe too much of the water in the frame. Not sure what to suggest.', '2008-03-20 13:51:08.000000', NULL, 1),
(4576994, 657967, 83313, '<td valign="top">Had to look a few moments to see it was a chrome bumper. Good job.</td>', 'Had to look a few moments to see it was a chrome bumper. Good job.', '2008-03-20 13:52:01.000000', NULL, 1),
(4576998, 658800, 83313, '<td valign="top">Makes my leftover hot dog eaten at my desk seem like fine dining. Thanks for putting things in perspective.</td>', 'Makes my leftover hot dog eaten at my desk seem like fine dining. Thanks for putting things in perspective.', '2008-03-20 13:53:34.000000', NULL, 1),
(4577004, 658784, 83313, '<td valign="top">Looks like one rose is gloating to the other. A little heavy on the saturation, otherwise I like it.</td>', 'Looks like one rose is gloating to the other. A little heavy on the saturation, otherwise I like it.', '2008-03-20 13:55:33.000000', NULL, 1),
(4577007, 658266, 83313, '<td valign="top">Great texture on this. Looks like you caught the magic light. Cropping seems a little too centered, otherwise I like it.</td>', 'Great texture on this. Looks like you caught the magic light. Cropping seems a little too centered, otherwise I like it.', '2008-03-20 13:56:41.000000', NULL, 1),
(4577010, 657388, 83313, '<td valign="top">I like the perspective through the peephole.</td>', 'I like the perspective through the peephole.', '2008-03-20 13:57:54.000000', NULL, 1),
(4577012, 657065, 83313, '<td valign="top">Yuck. But, that''s reality.</td>', 'Yuck. But, that''s reality.', '2008-03-20 13:58:18.000000', NULL, 1),
(4577016, 658736, 67001, '<td valign="top">I find this pic oversaturated. Would like to see it B+W.</td>', 'I find this pic oversaturated. Would like to see it B+W.', '2008-03-20 14:01:02.000000', NULL, 1),
(4577024, 657213, 83313, '<td valign="top">Not sure what you are trying to illustrate as being harsh here, but I like it. Maybe the harshness is life in general, and this persons dreams and aspirations are beating up against the hard wall of reality... (Oh geez, listen to me, I''m not that deep...)</td>', 'Not sure what you are trying to illustrate as being harsh here, but I like it. Maybe the harshness is life in general, and this persons dreams and aspirations are beating up against the hard wall of reality... (Oh geez, listen to me, I''m not that deep...)', '2008-03-20 14:04:34.000000', NULL, 1),
(4577026, 658031, 83313, '<td valign="top">Nice kitty!</td>', 'Nice kitty!', '2008-03-20 14:04:52.000000', NULL, 1),
(4577028, 658559, 83313, '<td valign="top">Pretty neat looking. I may have cropped out the mountain in the upper right. I think that may have helped it fit the title better.</td>', 'Pretty neat looking. I may have cropped out the mountain in the upper right. I think that may have helped it fit the title better.', '2008-03-20 14:06:01.000000', NULL, 1),
(4577029, 658208, 67001, '<td valign="top">You should have shown more context to your picture. I had no idea what it was before reading the title.</td>', 'You should have shown more context to your picture. I had no idea what it was before reading the title.', '2008-03-20 14:06:14.000000', NULL, 1),
(4577031, 658069, 83313, '<td valign="top">Seems a little over enhanced, perhaps trying to pull detail out of a dark eposure.</td>', 'Seems a little over enhanced, perhaps trying to pull detail out of a dark eposure.', '2008-03-20 14:07:23.000000', NULL, 1),
(4577081, 658731, 67258, '<td valign="top">An interesting idea, but I suspect I would prefer the photo if a little more texture was shown.</td>', 'An interesting idea, but I suspect I would prefer the photo if a little more texture was shown.', '2008-03-20 14:40:12.000000', NULL, 1),
(4577084, 658322, 67258, '<td valign="top">excellent title!</td>', 'excellent title!', '2008-03-20 14:41:41.000000', NULL, 1),
(4577091, 658799, 67258, '<td valign="top">A rose amongst thorns! For flora, this certainly is a harsh environment.</td>', 'A rose amongst thorns! For flora, this certainly is a harsh environment.', '2008-03-20 14:42:38.000000', NULL, 1),
(4577094, 658750, 67258, '<td valign="top">Your dreams scare me, too!  The smootheness of the mask contrasts well with the strong textures of the background, and the taught, convulsive hands.</td>', 'Your dreams scare me, too!  The smootheness of the mask contrasts well with the strong textures of the background, and the taught, convulsive hands.', '2008-03-20 14:45:36.000000', NULL, 1),
(4577097, 657235, 67258, '<td valign="top">Blimey, I have never seen anything like this!  Fascinating.</td>', 'Blimey, I have never seen anything like this!  Fascinating.', '2008-03-20 14:46:39.000000', NULL, 1),
(4577101, 658199, 67258, '<td valign="top">The almost post-apocolyptic style processing is a clever idea for the challenge, but I feel you needed to use it with a touch more subtlety - in particular, the horizon has a bright halo that I find somewhat distracting.</td>', 'The almost post-apocolyptic style processing is a clever idea for the challenge, but I feel you needed to use it with a touch more subtlety - in particular, the horizon has a bright halo that I find somewhat distracting.', '2008-03-20 14:49:09.000000', NULL, 1),
(4577108, 658622, 67258, '<td valign="top">Very good rendition of texture.  If the scene went further back, it might be interesting to see a portrait orientation showing the reeds receding into the background.</td>', 'Very good rendition of texture.  If the scene went further back, it might be interesting to see a portrait orientation showing the reeds receding into the background.', '2008-03-20 14:52:46.000000', NULL, 1),
